{
  "a_sentences": [
    {
      "a_text": "La question litigieuse porte sur les dommages à la toiture de la Focushalle, en particulier sur les dégâts à la dalle acoustique situés sous le toit.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle qu'il n'examine que les griefs invoqués et les vices juridiques manifestes, sous peine d'irrecevabilité.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La juridiction cantonale a retenu que la naissance d'une éventuelle créance de recours dépend de l'existence d'une responsabilité solidaire entre les coresponsables.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "En cas d'acceptation de l'ouvrage et de péremption des droits découlant des défauts, l'entrepreneur n'est plus responsable envers la maître d'ouvrage.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Cette péremption s'étend au rapport de recours entre l'architecte et l'entrepreneur, car celui qui n'est pas responsable envers le maître d'ouvrage ne doit pas non plus répondre solidairement.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral précise que la situation diffère de celle d'une créance prescrite, la péremption entraînant l'extinction totale de la prétention, contrairement à la prescription qui ne paralyse que l'action.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Il en résulte que l'absence de responsabilité de l'intimée envers la maître d'ouvrage, due à la péremption, exclut tout droit de recours de la recourante.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que la juridiction cantonale n'a pas violé le droit fédéral en niant un droit de recours de la recourante contre l'intimée pour les défauts devenus irrécouvrables.",
      "b_propositions": ["P8"]
    }
  ]
}
